import{_ as a,o,c as t,ap as i}from"./chunks/framework.Dv1_Li4I.js";const h=JSON.parse('{"title":"Statistical model ownership","description":"","frontmatter":{},"headers":[],"relativePath":"rkppl-smooths.md","filePath":"rkppl-smooths.md","lastUpdated":null}'),r={name:"rkppl-smooths.md"};function s(n,e,d,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="Statistical-model-ownership" tabindex="-1">Statistical model ownership <a class="header-anchor" href="#Statistical-model-ownership" aria-label="Permalink to &quot;Statistical model ownership {#Statistical-model-ownership}&quot;">​</a></h1><p>BayesianRegressionModels owns spline, HSGP, GP and varying-effect statistical preparation and model bodies for both backends. RK-PPL compiles ordinary model statements and does not ship a statistical model catalogue.</p><p>Obtain a BRM-owned body with <code>BayesianRegressionModels.rkppl_model</code>, bind it in the defining module, or pass prepared data matrices to a hand-authored model. Explicit coefficient priors, matrix products, truncated distributions, array indexing and function calls retain their authored Julia semantics. The <a href="./rkppl">RK-PPL guide</a> describes these general language capabilities.</p><p>Model-specific bases, spectral weights, defaults and scientific acceptance belong with the BRM implementation. PK-specific models and helpers belong to downstream RKPPLBench.</p><p>The PosteriorDB <code>one_comp_mm_elim_abs</code> model, full observation fixture and scientific oracle are maintained in RKPPLBench under <code>examples/posteriordb_pk/</code>. Its former RK-PPL example module and executable walkthrough are removed after that downstream adoption. General ODE and compiler machinery remain in ReactiveKernels.</p><p>Import preparation helpers from <code>BayesianRegressionModels.StatisticalPreparation</code> into the model module. The compiler no longer carries spline, HSGP, monotonic, DAR or varying-effect model IR. Varying effects are ordinary declared arrays and level gathers, or a BRM-owned <code>rkppl_model</code> body.</p><p>GP covariance functions and the native dual-HSGP motorcycle body are also owned by BRM, available at <code>1f296dac2c086347525194887500948edb213228</code>. Import <code>StatisticalPreparation.gp_exp_quad_cov</code>, <code>gp_periodic_cov</code> and <code>gp_chol_latent</code> as ordinary functions, or compose an assigned call to <code>BayesianRegressionModels.rk_model(:gp_exp_quad_cov)</code> / <code>rk_model(:gp_periodic_cov)</code>. The compiler uses its general module-binding and graph-composition paths. The <a href="./brm-hsgp">dual-HSGP consumer</a> delegates preparation and reads BRM&#39;s fixture; its statistical acceptance belongs to BRM. Dense lower Cholesky remains the general numerical callable <code>ReactiveKernels.rk_cholesky_lower</code>.</p>',7)])])}const _=a(r,[["render",s]]);export{h as __pageData,_ as default};
